style.css:
@-moz-document domain("github.com") {
/* 1. Fix Global Variables (using correct -- prefix) */
    :root {
        -color-canvas-default: #223657 !important;
        -color-canvas-subtle: #1a2a44 !important;
        -color-fg-default: white !important;
        -color-fg-muted: #d1d1d1 !important;
        /* Modern Primer variables for newer GitHub UI */
        -bgColor-default: #223657 !important;
        -fgColor-default: white !important;
    }

    /* 2. Main Layout Containers */
    .application-main, 
    .feed-main,
    .flex-auto > .d-md-flex,
    .col-md-8,
    .feed-left-sidebar,
    .loading-context,
    .pt-3 {
        background-color: #223657 !important;
    }

    /* 3. Text and Link Colors */
    .Stack,
    .d-flex > .f5,
    .flex-shrink-0,
    .footer-octicon > .octicon,
    .Link--primary,
    .Link--secondary,
    .px-4 .notice,
    .px-4 .f5 {
        color: white !important;
    }

    /* 4. Box Components */
    .Box {
        background-color: #1a2a44 !important;
        border-color: #30476e !important;
    }

    /* 5. Specific Overrides (Black Text for specific feed links) */
    .mt-1 > .px-3 .d-flex > .Link--primary,
    .mt-1:nth-child(2) > .px-3:nth-child(1) .pt-2:nth-child(2) .Link--primary:nth-child(2),
    div:nth-child(3) > .px-3 .d-flex > .Link--primary,
    div:nth-child(3) > .px-3:nth-child(1) .pt-2:nth-child(2) .Link--primary:nth-child(2) {
        color: black !important;
    }

    /* 6. Timeline Blue Links */
    .TimelineItem:nth-child(1) .Link--primary,
    .TimelineItem:nth-child(2) .Link--primary,
    .TimelineItem:nth-child(3) .Link--primary,
    .pb-0 > .TimelineItem-body > .Link--primary {
        color: #223657 !important;
    }
}
